changeSet.sql:
CREATE INDEX idx_user_photos_user_id
ON user_photos(user_id);

CREATE INDEX idx_user_photos_is_active
ON user_photos(is_active)
WHERE is_active = TRUE;

CREATE INDEX idx_photo_comments_photo_id
ON photo_comments(photo_id);

CREATE INDEX idx_photo_comments_user_id
ON photo_comments(user_id);

-- Функція для updated_at
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
NEW.updated_at = NOW();
RETURN NEW;
END;
$$;

-- Тригери
CREATE TRIGGER trg_user_photos_updated_at
BEFORE UPDATE ON user_photos
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER trg_photo_comments_updated_at
BEFORE UPDATE ON photo_comments
FOR EACH ROW EXECUTE FUNCTION set_updated_at();
